        foreach($actions as $action){$op=$action['operation'];$a=$action['arguments']??[];if(is_string($a))$a=json_decode($a,true)??[];$title=$a['title']??$a['name']??'';
            $type=match(explode('.',$op)[0]){'goal'=>'goals','task','checklist'=>'tasks','board'=>'boards','list'=>'lists','note'=>'notes','routine'=>'routines','map'=>'mapNodes',default=>null};if($type&&isset($a['id']))foreach($board[$type]??[] as $row)if($row['id']===$a['id'])$title=$row['title']??$row['name']??'';
            $name=$title!==''?'“'.$title.'”':'the item';$verb=match($op){'task.save','goal.save','board.save','list.save','note.save','routine.save'=>empty($a['id'])?'Added':'Updated','task.book'=>'Booked','task.move'=>'Moved','task.schedule'=>'Scheduled','checklist.toggle'=>($a['done']??false)?'Checked an item on':'Unchecked an item on','task.complete'=>($a['done']??false)?'Completed':'Reopened','task.archive','goal.archive','board.archive','list.archive','note.archive','map.archive'=>'Archived','task.restore','goal.restore','board.restore','list.restore','note.restore'=>'Restored','map.create'=>'Created mind map',default=>'Saved'};
