        return (bool)preg_match('/^(?:(?:please|okay|ok|now|just)[,\s.!:]*)*(?:(?:can|will|could|would) you\s+(?:please\s+)?)?(?:research|find|look up|search|queue public research)\b/iu',trim($message));
    }
