        $state['commands'][]=$receipt;$state['commands']=array_slice($state['commands'],-10);$updated=$ai->write($r['version'],$state);require_once __DIR__.'/google-sync.php';LifeGoogleSync::enqueue($store);$db->commit();unset($receipt['before'],$receipt['beforeMemories'],$receipt['beforeApplications'],$receipt['beforeOpportunities']);return $updated+['board'=>$board,'receipt'=>$receipt];
